function solve({config,state,event}){
  let s;
  if(state===null){s={v:config.initial,r:0,a:[],u:{},m:{}}}
  else{s={v:state.v,r:state.r,a:state.a.slice(),u:{},m:{}};for(let k in state.u)if(Object.prototype.hasOwnProperty.call(state.u,k))s.u[k]=1;for(let k of s.a){let q=state.m[k];s.m[k]={value:q.value,revision:q.revision}}}
  let t=event.type,id=event.id,status;
  if(t==='write'){
    if(event.expect!==s.r)status='conflict';
    else{s.v=event.value;s.r++;status='written'}
  }else if(t==='save'){
    if(Object.prototype.hasOwnProperty.call(s.u,id))status='exists';
    else{s.u[id]=1;s.m[id]={value:s.v,revision:s.r};s.a.push(id);while(s.a.length>config.keep){let x=s.a.shift();delete s.m[x]}status='saved'}
  }else if(t==='drop'){
    let i=s.a.indexOf(id);
    if(i<0)status='missing';
    else{s.a.splice(i,1);delete s.m[id];status='dropped'}
  }else if(t==='rollback'){
    if(event.expect!==s.r)status='conflict';
    else if(!Object.prototype.hasOwnProperty.call(s.m,id))status='missing';
    else{s.v=s.m[id].value;s.r++;status='rolled_back'}
  }
  let saved={};for(let k of s.a){let q=s.m[k];saved[k]={value:q.value,revision:q.revision}}
  return{state:s,output:{status:status,value:s.v,revision:s.r,snapshots:s.a.slice(),saved:saved}}
}
